    (1504::bigint, jsonb_build_object(
      'queue_wait', 'Popular drag shows fill the compact Night Bazaar room, so arrive 30–45 minutes before showtime for a seat. There may be no long outdoor line, only standing-room pressure. Check the current post for times, minimum order or reservation details.',
      'best_nights', 'Pick a night with the full cabaret and arrive early enough to enjoy the bar before the queens take over. Friday and Saturday feel most celebratory; quieter nights offer easier conversation. The show calendar matters more than a fixed weekly promise.',
      'crowd_mix', 'Gay men, queer travellers, Thai regulars, women, allies and drag fans make a visibly mixed audience. It is one of the easier Chiang Mai queer venues for a mixed group. Tourists are prominent near the Night Bazaar, but the performers give the room a local pulse.',
      'dress_code', 'Colourful casual is welcome: shorts, shirts, dresses, trainers and a little drag-night sparkle all fit. There is no reliable formal code. Keep the look breathable, leave room around performers and bring small notes if you plan to tip.',
      'staff_inclusivity', 'Reviews commonly praise energetic performers, a welcoming team and a fun, inclusive show. Busy service and tourist-zone pricing can vary, so order patiently and check the bill. The broad audience and drag-led format support a stronger inclusion signal than a generic bar listing.',
      'venue_classification', 'active_drag_led_lgbtq_bar_near_chiang_mai_night_bazaar_with_compact_cabaret_room_mixed_gay_queer_woman_ally_tourist_thai_audience_weekend_peak_and_strong_fun_welcoming_consensus',
      'identity_note', 'Ram Bar is a drag and cabaret-led LGBTQ+ bar near the Night Bazaar, not a men-only host venue. Show timing and seating are central to the visit.',
      'source_urls', to_jsonb(array['https://www.rambarchiangmai.com/','https://www.travelgay.com/venue/ram-bar','https://www.tripadvisor.com/Attraction_Review-g293917-d17394351-Reviews-Ram_Bar-Chiang_Mai.html','https://wanderlog.com/place/details/1762719/ram-bar-chiangmai']::text[]),
