    (1506::bigint, jsonb_build_object(
      'queue_wait', 'This huge Nimman institution can create an ID and security line after 22:00, especially Friday and Saturday. Arrive earlier for food and a table, or book when the venue offers it. Carry a physical passport or accepted ID and expect bag checks.',
      'best_nights', 'Friday and Saturday deliver the full live-band, courtyard and club-room spectacle. A weekday is easier for dinner, Thai pop and conversation without the crush. Follow the current lineup: different rooms and performers can turn the same venue into very different nights.',
      'crowd_mix', 'Young Thai students, professionals, domestic visitors and international travellers dominate. LGBTQ+ guests and mixed friend groups attend, but this is mainstream nightlife, not a gay bar. The crowd is fashionable, social and overwhelmingly local compared with tourist-strip clubs.',
      'dress_code', 'Smart casual is the safe choice: clean trainers or shoes, neat tops and polished shorts or trousers. Avoid beachwear and overly casual sandals on a club night. Bring physical ID, dress for heat outdoors and air-conditioning inside, and expect a visibly styled crowd.',
      'staff_inclusivity', 'The venue is broadly mixed and popular, but no dedicated LGBTQ+ mission or staff training evidence surfaced. Reviews praise production, music and energetic service while noting crowds and uneven door experiences. Queer guests should expect mainstream hospitality, not community-specific care.',
      'venue_classification', 'active_large_mainstream_nimman_nightlife_complex_with_restaurant_live_music_courtyard_and_club_spaces_young_thai_local_core_mixed_visitors_weekend_id_security_lines_and_no_verified_dedicated_lgbtq_identity',
      'identity_note', 'Warm Up Cafe is a mainstream Chiang Mai nightlife institution, not a gay bar. LGBTQ+ people attend within a broad mixed crowd, but the record should not imply queer ownership or programming.',
      'source_urls', to_jsonb(array['https://www.warmupcafe1999.com/','https://www.wongnai.com/restaurants/807EV-warm-up-cafe','https://www.tripadvisor.com/Restaurant_Review-g293917-d3704115-Reviews-Warm_Up_Cafe-Chiang_Mai.html','https://www.facebook.com/warmupcafechiangmai/']::text[]),
