        'dress_code', jsonb_build_object('status','optional_boot_denim_theme_style_with_danceable_shoes_layers_and_physical_id_priority','source_urls',to_jsonb(array['https://www.charlieschicago.com/','https://www.instagram.com/charlieschicago/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
