    (954::bigint, jsonb_build_object(
      'queue_wait', 'The South Side room is usually accessible early, while major drag, DJ and community nights can create an ID check and short door line. The patio adds breathing room in season. Check the flyer for cover and start time, and bring physical government ID.',
      'best_nights', 'Go for a posted drag show, DJ party or community gathering; weekend nights animate both the dance floor and large patio. Earlier hours are conversational, later ones celebratory. The programme matters because this neighborhood bar shifts easily between lounge and club energy.',
      'crowd_mix', 'Black LGBTQ+ Chicagoans are the historic heart, joined by queer people across genders, South Side regulars, friends and visitors. The crowd is community-led and notably more diverse than many Northalsted rooms. Drag nights broaden the mix further.',
      'dress_code', 'Come in polished casual clothes, expressive nightlife style or whatever the event invites. There is no dependable formal code, though a clean, intentional look fits. Bring a patio layer, danceable shoes and valid ID; special themes may reward glamour without requiring it.',
      'staff_inclusivity', 'Its longevity and South Side LGBTQ+ community role are meaningful inclusion signals, and guests often praise the friendly atmosphere and patio. As with any busy late bar, service and security experiences vary. Confirm prices and address concerns calmly with management.',
      'venue_classification', 'active_long_running_black_lgbtq_centered_south_side_chicago_bar_and_dance_club_with_drag_djs_large_patios_community_events_broad_queer_gender_mix_and_positive_neighborhood_role_with_busy_night_variability',
      'identity_note', 'The stored “Escape” record is Club Escape at 1530 E 75th Street, an active South Side LGBTQ+ bar and club—not a Northalsted venue or a generic escape-room attraction.',
      'source_urls', to_jsonb(array['https://www.clubescape.com/','https://www.instagram.com/clubescapechicago/','https://chicago.gopride.com/directory/business.cfm/club-escape/chicago/id/10980321','https://qa.time.com/5614211/lgbtq-bars-after-stonewall/','https://news.wttw.com/sites/default/files/article/file-attachments/Out%20Chicago%20LGBTQ%20Visitor%27s%20Guide.pdf']::text[]),
