    (437::bigint, jsonb_build_object(
      'queue_wait', 'Before the headline DJ or late show, entry is manageable; peak Saturday and festival weekends can mean a real line, cover and a packed bar. Buy advance tickets when offered, bring physical 21+ ID and read the event’s entry rules before arriving.',
      'best_nights', 'Friday drag showcases, Saturday circuit and house bookings, Sunday Funday and select weekday shows each have distinct audiences. For serious dancing, follow the DJ rather than the weekday. The room often becomes strongest after midnight and runs very late.',
      'crowd_mix', 'Gay men anchor the late dance floor, joined by queer women, trans and nonbinary guests, drag fans, allies and international party travellers. Circuit nights skew male and body-conscious; drag and Sunday programming broaden the room. Energy is more club than neighborhood bar.',
      'dress_code', 'Dance-floor clothes win: tanks, tees, shorts, trainers, fetish accents or a polished club look. Dress for sweat and protect your hearing. There is no single style gate beyond event rules and legal ID, but special parties may set a theme or stricter bag policy.',
      'staff_inclusivity', 'Recent reviews praise strong drinks, DJs, drag, dancers and a staff that keeps busy nights moving; others note crowding, steep peak cover or intoxicated guests. The LGBTQ+ identity is explicit. Keep your drink in sight and seek security promptly if consent or safety slips.',
      'venue_classification', 'active_late_night_northalsted_lgbtq_dance_club_with_house_circuit_djs_drag_gogo_sunday_programming_gay_male_core_broader_queer_audience_peak_lines_cover_and_strong_recent_entertainment_consensus',
      'identity_note', 'Hydrate is an active 21+ LGBTQ+ late-night dance club at 3458 N Halsted, with programming that ranges from drag to international house and circuit DJs.',
      'source_urls', to_jsonb(array['https://hydratechicago.com/','https://hydratechicago.com/frequently-asked-questions/','https://hydratechicago.com/reviews/','https://chicago.gaycities.com/bars/174-hydrate-nightclub','https://www.tripadvisor.com/Attraction_Review-g35805-d10080353-Reviews-Hydrate_Nightclub-Chicago_Illinois.html']::text[]),
      'topic_evidence', jsonb_build_object(
