        'crowd_mix', jsonb_build_object('status','gay_male_core_with_queer_woman_trans_nonbinary_drag_fan_ally_and_international_party_mix_by_event','source_urls',to_jsonb(array['https://hydratechicago.com/reviews/','https://www.tripadvisor.com/Attraction_Review-g35805-d10080353-Reviews-Hydrate_Nightclub-Chicago_Illinois.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','sweat_ready_clubwear_optional_fetish_theme_hearing_protection_event_bag_rules_and_id','source_urls',to_jsonb(array['https://hydratechicago.com/frequently-asked-questions/','https://hydratechicago.com/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
