        'best_nights', jsonb_build_object('status','drag_viewing_weekend_dance_weekday_trivia_karaoke_patio_and_event_led_choice','source_urls',to_jsonb(array['https://roscoes.com/','https://www.instagram.com/roscoestavern/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','gay_male_core_drag_fan_queer_woman_trans_nonbinary_ally_tourist_birthday_and_age_varied_daytime_mix','source_urls',to_jsonb(array['https://www.tripadvisor.com/Attraction_Review-g35805-d563918-Reviews-Roscoe_s_Tavern-Chicago_Illinois.html','https://chicago.gaycities.com/bars/171-roscoes-tavern']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code', jsonb_build_object('status','day_casual_to_viewing_party_glamour_with_dance_shoes_physical_id_and_patio_indoor_layers','source_urls',to_jsonb(array['https://roscoes.com/','https://www.instagram.com/roscoestavern/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','upbeat_bartender_drag_welcome_praise_balanced_by_peak_service_crowding_and_door_friction','source_urls',to_jsonb(array['https://www.opentable.com/r/roscoes-tavern-chicago','https://www.tripadvisor.com/Attraction_Review-g35805-d563918-Reviews-Roscoe_s_Tavern-Chicago_Illinois.html']::text[]),'checked_at','2026-08-07T00:00:00Z')
      ),'research_status','editorial_review_consensus','updated_at','2026-08-07T00:00:00Z'
